use vstd::prelude::*;

verus! {

/// Spec view of broadcasting:
/// - output length is max(|a|, |b|)
/// - each output element comes from either the corresponding element (if len > 1)
///   or index 0 (if len == 1)
spec fn bcast_index(len: nat, i: nat) -> nat {
    if len == 1 { 0 } else { i }
}

spec fn bcast_len(m: nat, n: nat) -> nat {
    if m >= n { m } else { n }
}

fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (out_a: Vec<i8>, out_b: Vec<i8>)
    requires
        a.len() > 0,
        b.len() > 0,
        a.len() == b.len() || a.len() == 1 || b.len() == 1,
    ensures
        out_a.len() == bcast_len(a.len() as nat, b.len() as nat),
        out_b.len() == bcast_len(a.len() as nat, b.len() as nat),

        // Broadcasting semantics for all indices
        forall|i: nat|
            i < out_a.len() as nat ==>
                out_a[i as int] == a[bcast_index(a.len() as nat, i) as int],
        forall|i: nat|
            i < out_b.len() as nat ==>
                out_b[i as int] == b[bcast_index(b.len() as nat, i) as int],
{
    let m = a.len();
    let n = b.len();
    let out_len: usize = if m >= n { m } else { n };

    let mut oa: Vec<i8> = Vec::new();
    let mut ob: Vec<i8> = Vec::new();

    let mut i: usize = 0;
    while i < out_len
        invariant
            a.len() > 0,
            b.len() > 0,
            a.len() == b.len() || a.len() == 1 || b.len() == 1,

            out_len == (if a.len() >= b.len() { a.len() } else { b.len() }),
            i <= out_len,

            oa.len() == i,
            ob.len() == i,

            // oa/ob match the broadcast spec on all filled indices
            forall|j: nat|
                j < i as nat ==>
                    oa[j as int] == a[bcast_index(a.len() as nat, j) as int],
            forall|j: nat|
                j < i as nat ==>
                    ob[j as int] == b[bcast_index(b.len() as nat, j) as int],
        decreases out_len - i,
    {
        let ia: usize = if m == 1 { 0 } else { i };
        let ib: usize = if n == 1 { 0 } else { i };

        // These are safe due to compatibility and out_len = max(m,n)
        assert(ia < m) by {
            if m == 1 {
                assert(ia == 0);
            } else {
                // m != 1 so either m == out_len or (if n==1 then out_len==m)
                assert(m > 1);
                assert(i < out_len);
                // If m != 1, broadcasting requires m == out_len (since either m==n or n==1)
                // More explicitly:
                if m == n {
                    assert(out_len == m);
                } else {
                    // then must have n == 1 by precondition (since m != 1)
                    assert(n == 1);
                    assert(out_len == m);
                }
                assert(i < m);
            }
        }
        assert(ib < n) by {
            if n == 1 {
                assert(ib == 0);
            } else {
                assert(n > 1);
                assert(i < out_len);
                if m == n {
                    assert(out_len == n);
                } else {
                    // then must have m == 1 by precondition (since n != 1)
                    assert(m == 1);
                    assert(out_len == n);
                }
                assert(i < n);
            }
        }

        oa.push(a[ia]);
        ob.push(b[ib]);
        i = i + 1;
    }

    (oa, ob)
}

} // verus!

